         top: 1rem;
         left: 1rem;
         width: auto;
         height: auto;
         margin: 0;
         clip: auto;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--text);
         color: #fff;
         z-index: 10;
       }

       .page-shell {
         padding: 2rem 1rem 3rem;
       }

       .product-shell {
         width: min(100%, 42rem);
         margin: 0 auto;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         padding: 0.45rem 0.75rem;
         border-radius: 999px;
         background: rgba(255, 255, 255, 0.72);
         border: 1px solid rgba(79, 70, 229, 0.12);
         color: var(--accent-strong);
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.01em;
       }

       .card {
         margin-top: 1rem;
         padding: clamp(1.5rem, 4vw, 2.5rem);
         border-radius: 1.5rem;
         background: var(--panel);
         border: 1px solid var(--panel-border);
         box-shadow: var(--shadow);
         backdrop-filter: blur(16px);
       }

       h1 {
         margin: 1rem 0 0.75rem;
         font-size: clamp(2rem, 5vw, 3rem);
         line-height: 1.05;
       }

       .lede {
         margin: 0 0 1.75rem;
         max-width: 46ch;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         padding: 1rem;
         border-radius: 1rem;
         background: rgba(255, 255, 255, 0.9);
         border: 1px solid rgba(148, 163, 184, 0.28);
       }

       .checkbox-label {
         display: grid;
         grid-template-columns: auto 1fr;
         gap: 0.875rem;
         align-items: start;
         font-weight: 600;
         line-height: 1.5;
         cursor: pointer;
       }

       input[type="checkbox"] {
         inline-size: 1.2rem;
         block-size: 1.2rem;
         margin: 0.1rem 0 0;
         accent-color: var(--accent);
       }

       .required-mark {
         color: var(--accent-strong);
       }

       .helper-text,
       .error-text,
       .status-text {
         margin: 0.65rem 0 0;
         font-size: 0.95rem;
         line-height: 1.5;
       }

       .helper-text {
         color: var(--muted);
       }

       .error-text {
         color: var(--error);
         font-weight: 600;
       }

       .status-text {
         min-height: 1.5rem;
         color: var(--success);
         font-weight: 600;
       }

       button {
         justify-self: start;
         min-width: 9rem;
         padding: 0.9rem 1.25rem;
         border: 0;
         border-radius: 999px;
         background: linear-gradient(135deg, var(--accent) 0%, #7c3aed 100%);
         color: #fff;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 14px 30px rgba(79, 70, 229, 0.26);
       }

       :focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: 3px;
       }

       input[aria-invalid="true"] + .checkbox-copy {
         color: var(--error);
       }

       .form-field[data-invalid="true"] {
         border-color: rgba(185, 28, 28, 0.42);
         background: rgba(254, 242, 242, 0.95);
       }

       @media (max-width: 40rem) {
         .page-shell {
           padding-inline: 0.875rem;
         }

         button {
           width: 100%;
           justify-self: stretch;
         }
       }

       @media (prefers-reduced-motion: no-preference) {
         .card {
           animation: float-in 240ms ease-out;
         }

         button {
           transition: transform 160ms ease, box-shadow 160ms ease;
         }

         button:hover {
           transform: translateY(-1px);
           box-shadow: 0 18px 34px rgba(79, 70, 229, 0.3);
         }
       }

       @keyframes float-in {
         from {
           opacity: 0;
           transform: translateY(10px);
         }
         to {
           opacity: 1;
           transform: translateY(0);
         }
       }

       @media (forced-colors: active) {
         body {
           background: Canvas;
         }

         .card,
         .form-field,
         .eyebrow {
           background: Canvas;
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         button {
           background: ButtonFace;
           color: ButtonText;
           border: 1px solid ButtonText;
           box-shadow: none;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="app"></div>
     <script>
       const CheckboxField = ({
         inputId,
         helperId,
         errorId,
         label,
         helperText,
       }) => `
         <div class="form-field" data-invalid="false">
           <label class="checkbox-label" for="${inputId}">
              <input
                id="${inputId}"
                name="${inputId}"
                type="checkbox"
                required
                aria-describedby="${helperId}"
                aria-errormessage="${errorId}"
              />
             <span class="checkbox-copy">
               ${label}
               <span class="required-mark" aria-hidden="true">*</span>
               <span class="sr-only"> required</span>
             </span>
           </label>
           <p id="${helperId}" class="helper-text">${helperText}</p>
           <p id="${errorId}" class="error-text" hidden>
             Error: Please agree to the Terms of Use to continue.
           </p>
         </div>
       `;

       const ConsentForm = () => `
         <form data-consent-form novalidate>
           ${CheckboxField({
             inputId: "consent",
             helperId: "consent-help",
             errorId: "consent-error",
             label: "I agree to the Terms of Use",
             helperText: "Required to continue with setup.",
           })}
           <button type="submit">Continue</button>
           <p class="status-text" id="form-status" aria-live="polite"></p>
         </form>
       `;

       const App = () => `
         <main id="maincontent" class="page-shell" tabindex="-1">
           <section class="product-shell" aria-labelledby="page-title">
             <div class="eyebrow">Secure product access</div>
             <div class="card">
               <h1 id="page-title">Confirm your terms consent</h1>
               <p class="lede">
                 Review the final step and confirm you agree before continuing.
               </p>
               ${ConsentForm()}
             </div>
           </section>
         </main>
       `;

       const root = document.getElementById("app");
       root.innerHTML = App();

       const form = document.querySelector("[data-consent-form]");
       const checkbox = document.getElementById("consent");
       const error = document.getElementById("consent-error");
       const status = document.getElementById("form-status");
       const field = checkbox.closest(".form-field");

       const setInvalidState = (isInvalid) => {
         field.dataset.invalid = String(isInvalid);
         error.hidden = !isInvalid;

         if (isInvalid) {
           checkbox.setAttribute("aria-invalid", "true");
         } else {
           checkbox.removeAttribute("aria-invalid");
         }
       };

       checkbox.addEventListener("change", () => {
         status.textContent = "";
         if (checkbox.checked) {
           setInvalidState(false);
         }
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.textContent = "";

         if (!checkbox.checked) {
           setInvalidState(true);
           checkbox.focus();
           return;
         }

         setInvalidState(false);
         status.textContent = "Thanks — your consent has been recorded for this session.";
       });
     </script>
   </body>
 </html>

')
